'use strict';
const $=s=>document.querySelector(s);
const inputs=['energy','height','width'].map(id=>$('#'+id));let paused=matchMedia('(prefers-reduced-motion: reduce)').matches,phase=0,model,params;
function update(event){let[E,V,a]=inputs.map(x=>+x.value);if(E>=V){E=Math.max(.05,V-.01);inputs[0].value=E;}inputs[0].max=(V-.01).toFixed(2);params={E,V,a};model=Quantum.state(E,V,a);$('#energyOut').textContent=E.toFixed(2)+' eV';$('#heightOut').textContent=V.toFixed(2)+' eV';$('#widthOut').textContent=a.toFixed(2)+' nm';$('#transmission').textContent=(model.T*100).toFixed(model.T<.001?4:2)+'%';$('#conservation').textContent='T + R = '+(model.T+model.R).toFixed(6);drawTrend();drawWave();}
function setup(canvas){const small=canvas.getBoundingClientRect().width<500,desired=small?650:1000;if(canvas.width!==desired)canvas.width=desired;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.lineWidth=2;ctx.font=(small?'26':'20')+'px Arial';ctx.fillStyle='#607375';ctx.strokeStyle='#ccd5ce';return{ctx,w,h};}
function drawWave(){if(!model)return;const{ctx:c,w,h}=setup($('#wave')),l=54,r=w-20,t=32,b=h-65,xmin=-.8,xmax=params.a+.9,xx=x=>l+(x-xmin)/(xmax-xmin)*(r-l),yy=y=>b-(y+1.9)/6.1*(b-t);
c.fillStyle='#f5e4c9';c.fillRect(xx(0),t,xx(params.a)-xx(0),b-t);c.strokeStyle='#cdd6d0';c.beginPath();c.moveTo(l,t);c.lineTo(l,b);c.lineTo(r,b);c.stroke();c.beginPath();c.moveTo(l,yy(0));c.lineTo(r,yy(0));c.stroke();
c.fillStyle='#607375';c.fillText('relative scale',l+8,25);c.fillText('x (nm)',r-c.measureText('x (nm)').width,h-4);for(let x of new Set([xmin,0,params.a,xmax])){const text=x.toFixed(2);c.fillText(text,Math.min(r-c.measureText(text).width,Math.max(0,xx(x)-20)),h-33);}for(let y of [0,2,4])c.fillText(y,18,yy(y)+7);
for(let density of [false,true]){c.strokeStyle=density?'#ae751e':'#157b73';c.lineWidth=3;c.beginPath();for(let i=0;i<=500;i++){const x=xmin+(xmax-xmin)*i/500,p=model.psi(x),y=density?Quantum.abs2(p):p[0]*Math.cos(phase)+p[1]*Math.sin(phase);if(i===0)c.moveTo(xx(x),yy(y));else c.lineTo(xx(x),yy(y));}c.stroke();}}
function drawTrend(){const{ctx:c,w,h}=setup($('#trend')),l=54,r=w-20,t=32,b=h-65,xx=x=>l+x/1.2*(r-l),yy=y=>b-y*(b-t);c.strokeStyle='#ccd5ce';c.beginPath();c.moveTo(l,t);c.lineTo(l,b);c.lineTo(r,b);c.stroke();c.fillStyle='#607375';c.fillText('T',10,28);c.fillText('a (nm)',r-c.measureText('a (nm)').width,h-1);for(let y of [0,.5,1])c.fillText(y,10,yy(y)+7);for(let x of [0,.3,.6,.9,1.2])c.fillText(x.toFixed(1),Math.min(r-c.measureText(x.toFixed(1)).width,xx(x)-13),h-33);c.strokeStyle='#157b73';c.lineWidth=3;c.beginPath();for(let i=0;i<=240;i++){const a=i/200,y=Quantum.transmission(params.E,params.V,a);if(i===0)c.moveTo(xx(a),yy(y));else c.lineTo(xx(a),yy(y));}c.stroke();c.fillStyle='#ae751e';c.beginPath();c.arc(xx(params.a),yy(model.T),7,0,Math.PI*2);c.fill();}
inputs.forEach(e=>e.addEventListener('input',update));$('#reset').onclick=()=>{inputs[0].max=.99;inputs.forEach((e,i)=>e.value=[.5,1,.45][i]);update();};function motionLabel(){$('#motion').textContent=paused?'Play animation':'Pause animation';$('#motion').setAttribute('aria-pressed',String(paused));}$('#motion').onclick=()=>{paused=!paused;motionLabel();};motionLabel();update();let prev=0;function frame(now){if(!paused&&now-prev>40){phase=now/1100;drawWave();prev=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
const lecture = new CourseVideo("lectureVideo");
const cfg=window.COURSE_CONFIG||{};if(cfg.youtubeUrl){$('#youtubeLink').href=cfg.youtubeUrl;$('#youtubeLink').hidden=false;}if(cfg.h5pUrl){$('#h5pLink').href=cfg.h5pUrl;$('#h5pLink').textContent='Launch the H5P version ↗';}
function time(s){return Math.floor(s/60).toString().padStart(2,'0')+':'+Math.floor(s%60).toString().padStart(2,'0');}
fetch('chapters.json').then(r=>r.json()).then(chapters=>{for(const ch of chapters){const b=document.createElement('button');const stamp=document.createElement('span');stamp.textContent=time(ch.start);b.append(stamp,document.createTextNode(ch.title));b.onclick=()=>{lecture.seek(ch.start);lecture.play();document.querySelector('#lecture').scrollIntoView({block:'start'});};$('#chapters').append(b);}}).catch(()=>$('#chapters').textContent='Chapter index is unavailable. Serve this folder over HTTP.');
let questions=[],qi=0;fetch('quizzes.json').then(r=>r.json()).then(q=>{questions=q;showQuiz();}).catch(()=>$('#quiz').textContent='Question data unavailable. Serve this folder over HTTP.');
function showQuiz(){const q=questions[qi],area=$('#quiz');area.replaceChildren();const count=document.createElement('div');count.className='count';count.textContent=`QUESTION ${qi+1} OF ${questions.length}`;const title=document.createElement('h3');title.textContent=q.question;const form=document.createElement('form'),opts=document.createElement('div');opts.className='options';q.options.forEach((text,i)=>{const label=document.createElement('label');label.className='option';const input=document.createElement('input');input.type='radio';input.name='answer';input.value=i;input.required=true;label.append(input,document.createTextNode(text));opts.append(label);});const check=document.createElement('button');check.type='submit';check.className='button';check.textContent='Check reasoning →';const feedback=document.createElement('div');feedback.hidden=true;feedback.className='feedback';feedback.setAttribute('role','status');const next=document.createElement('button');next.type='button';next.className='secondary';next.textContent=qi===questions.length-1?'Start again ↺':'Next question →';next.hidden=true;next.onclick=()=>{qi=(qi+1)%questions.length;showQuiz();};form.onsubmit=event=>{event.preventDefault();const selected=form.querySelector('input:checked');if(!selected)return;const correct=+selected.value===q.correct_index;feedback.textContent=(correct?'Correct. ':'Reconsider. ')+q.explanation+' Explain the answer in your own words before moving on.';feedback.hidden=false;next.hidden=false;};form.append(opts,check,next,feedback);area.append(count,title,form);}
